  "ui.wpAdminAgentFrameApp.feedback100": "اجراکنندهٔ CLI محلی در دسترس نیست. تنظیمات ← اجرا را باز کنید و OpenCode یا اجراکنندهٔ پشتیبانی‌شدهٔ دیگری را متصل کنید.",
