  "wp.message.26a6374fbf59": "یکی از افزونه‌های Pixflow راه‌اندازی نشد. سازگاری افزونه‌های Pixflow را بررسی کنید و صفحه را دوباره بارگذاری کنید. سایر قابلیت‌ها ممکن است همچنان در دسترس باشند.",
  "wp.message.ca7714cffbcc": "فعال‌سازی Pro",
  "wp.message.197c83a2f752": "با افزونهٔ Pro ابزارهای حرفه‌ای خود را بازگردانید. مجوز، محتوا و تنظیمات ذخیره‌شدهٔ شما حفظ می‌شوند. اگر از احراز هویت دومرحله‌ای Bricks استفاده می‌کردید، پس از فعال‌سازی Pro آن را در تنظیمات دوباره فعال کنید.",
  "wp.message.2ffdcbc380ea": "با صفحه‌ساز دلخواهتان بسازید. یادداشت‌گذاری، صدا، سیستم‌های طراحی و تولید تصویر را به روند کارتان اضافه کنید.",
  "wp.message.40ed1102964b": "بررسی دورهٔ آزمایشی Pro",
  "wp.message.e9cccd3ef5fc": "ذخیرهٔ بستن اعلان ممکن نشد. دوباره تلاش کنید.",
  "wp.message.1372089fb797": "بستن بنر Pixflow Pro",
  "wp.message.5e3ba715018d": "دریافت Pro",
  "wp.message.fb2e6d87b44c": "امکانات بیشتر با Pixflow Design Pro",
  "wp.message.9934717ca744": "این صفحه را تازه‌سازی و دوباره تلاش کنید.",
  "wp.message.7c78f9990490": "دورهٔ آزمایشی ۷روزهٔ Pro را شروع کنید",
  "wp.message.f89b4dcf2c2e": "Pro را ۷ روز امتحان کنید",
  "wp.message.69ecce9deb2d": "اجازهٔ بستن این اعلان را ندارید.",
  "wp.message.927384e7eed8": "طرح Pixflow شما شامل Pro است",
