  "wp.message.0d1fa0dfcc9e": "کد ۶رقمی",
  "wp.message.8b6693be283d": "پنل حساب",
  "wp.message.107a3671eb84": "رنگ فعال/تکمیل‌شده",
  "wp.message.47d932f4c02a": "رنگ شمارهٔ فعال/تکمیل‌شده",
  "wp.message.73dbcf028ec6": "برای محافظت از حسابتان یک روش تأیید دوم اضافه کنید.",
  "wp.message.529da8588051": "برای تکمیل ورود، تأیید بیشتری لازم است.",
  "wp.message.6b49000156c3": "وقتی کاربر همهٔ روش‌های احراز هویت و کدهای بازیابی را از دست داده، مدیران می‌توانند از این بازنشانی اضطراری استفاده کنند.",
  "wp.message.4ea44caf5d6e": "بعد از فرم",
  "wp.message.1be05927766c": "یکی از مدیران احراز هویت دومرحله‌ای را از حساب شما حذف کرده است. اگر انتظار این تغییر را نداشتید، رمز عبورتان را بازنشانی کنید و فوراً با مدیر سایت تماس بگیرید.",
  "wp.message.bd4a7c92a53f": "پنجرهٔ احراز هویت/ایمیل/کلید عبور",
  "wp.message.09a12ace273f": "برنامهٔ احراز هویت",
  "wp.message.a4c801f3d189": "برنامهٔ احراز هویت آماده است",
  "wp.message.9fd5a3f4f23e": "راه‌اندازی برنامهٔ احراز هویت برای این سایت غیرفعال است.",
  "wp.message.7258165188b4": "توضیح برنامهٔ احراز هویت",
  "wp.message.7cb96fa5a704": "پیش‌نمایش کد QR احراز هویت",
  "wp.message.838557924a5c": "پشتیبان",
  "wp.message.216f00eada6a": "قبل از فرم",
  "wp.message.9e2b8fcf9a19": "جای‌نگهدار محتوای مسدودشده",
  "wp.message.745c19fce0bf": "جای‌نگهدار محتوای مسدودشده",
  "wp.message.de4aeff9ee43": "تایپوگرافی متن اصلی",
  "wp.message.45e9870097b1": "فقط در صفحه‌ساز. هنگام استایل‌دهی به عناصر دیگر، پیش‌نمایش انتخاب‌شده را باز نگه دارید.",
  "wp.message.c3d4759d35d0": "پیش‌نمایش صفحه‌ساز",
  "wp.message.5be164b5cb70": "نمی‌توانید اسکن کنید؟ این کلید راه‌اندازی را دستی وارد کنید:",
