  "wp.message.145824df14a5": "فاصلهٔ داخلی",
  "wp.message.66d7671d170d": "آخرین نسخهٔ افزونهٔ Google Site Kit را نصب و سرویس ورود با Google را در این بخش تنظیم کنید:",
  "wp.message.793e6000d1b8": "احراز هویت دومرحله‌ای تعاملی لازم است؛ برای دسترسی API از رمز عبور برنامهٔ WordPress استفاده کنید.",
  "wp.message.401802b23430": "درخواست فونت متغیر Pixflow نامعتبر است.",
  "wp.message.86aaa00d0f04": "خالی است",
  "wp.message.5a78c3a30610": "خالی نیست",
  "wp.message.d1b1ea7575cf": "هنگام استایل‌دهی باز بماند",
  "wp.message.1314f2e8976d": "بنر اصلی کوکی",
