  "wp.message.2346f214ad56": "کم‌رنگ",
  "wp.message.d8289dfcd433": "درخواست تأیید فعال برای ورود با Google پیدا نشد.",
  "wp.message.cd8dedfb1ee6": "درخواست فعال احراز هویت دومرحله‌ای پیدا نشد.",
  "wp.message.5749e7cab8b4": "کلید عبور — در حال راه‌اندازی",
  "wp.message.ef748333e03d": "توضیح کلید عبور",
  "wp.message.dd8c3b5e38b9": "کلید عبور یا کلید امنیتی",
  "wp.message.d5dedb552cfa": "راه‌اندازی کلید عبور برای این سایت غیرفعال است.",
  "wp.message.594d0d476015": "کلیدهای عبور و کلیدهای امنیتی",
  "wp.message.56da94bc376c": "کلیدهای عبور به HTTPS و افزونه‌های OpenSSL و mbstring در PHP نیاز دارند.",
  "wp.message.1d3f35031a5a": "کد سفارشی Splide در Pixflow",
  "wp.message.b73a688afd1a": "Pixflow Design Pro به نسخهٔ سازگار افزونهٔ اصلی Pixflow Design نیاز دارد. هر دو افزونه را با هم به‌روزرسانی کنید.",
  "wp.message.7ecf123f8f20": "برای Pixflow Design Pro باید افزونهٔ اصلی Pixflow Design فعال باشد.",
  "wp.message.46d86360f524": "احراز هویت دومرحله‌ای Pixflow",
  "wp.message.e70f8f3b8315": "این عنصر را یک بار در قالب پابرگ سراسری Bricks قرار دهید. خدمات رضایت، شناسایی و مسدودسازی در Pixflow Design ← افزونه‌های Bricks ← رضایت کوکی تنظیم می‌شوند.",
  "wp.message.6d031af10da7": "موقعیت",
  "wp.message.72d7dc1a93b5": "موقعیت‌دهی",
  "wp.message.1783ebab33ee": "پنجرهٔ ترجیحات",
  "wp.message.758885fbfb64": "پنجرهٔ ترجیحات",
  "wp.message.8e314cb69749": "تعداد محصولات",
  "wp.message.c76c9e7682bc": "شناسهٔ محصول",
  "wp.message.4edc8bfafc6b": "محصولات",
  "wp.message.c6971d403239": "محصولات اخیراً مشاهده‌شده",
  "wp.message.5bda8302b5ec": "کد بازیابی",
  "wp.message.36880d15c890": "کدهای بازیابی",
  "wp.message.22ba7abac520": "توضیح بازیابی",
  "wp.message.c7901fa498bb": "متن دکمهٔ ارسال بازیابی",
  "wp.message.2374561a7b97": "همهٔ روش‌های ثبت‌شده، کلیدهای عبور و کدهای بازیابی را حذف کنید.",
  "wp.message.77bbc9ed8bef": "دکمهٔ متصل ورود با Google در Google Site Kit را داخل این فرم نمایش دهید.",
  "wp.message.858bbbd0f6e8": "ارسال دوباره در 1:00",
  "wp.message.01c88bb1a49f": "بازنشانی احراز هویت دومرحله‌ای",
  "wp.message.e569a7dd5f6d": "بازنشانی همهٔ روش‌های احراز هویت دومرحله‌ای",
  "wp.message.5362713d638e": "دکمهٔ بازنشانی",
  "wp.message.0b443363f14e": "این کدهای بازیابی یک‌بارمصرف را در جای امنی ذخیره کنید. آن‌ها فقط یک بار نمایش داده می‌شوند.",
  "wp.message.76e07d866ee3": "این کد QR را با برنامهٔ احراز هویت اسکن کنید، سپس برای تأیید کد شش‌رقمی ادامه دهید.",
  "wp.message.62f2ccfffcc5": "ثانویه",
  "wp.message.193a98699d02": "حسابتان را ایمن کنید",
  "wp.message.753a970dd23f": "پیش از تکمیل این ورود در WordPress، حسابتان را ایمن کنید.",
  "wp.message.aba5693ac28d": "در حال انتخاب",
  "wp.message.d8d92d22f721": "ارسال کد ایمیلی",
  "wp.message.19e86d2b7055": "ارسال کد تأیید",
  "wp.message.4da10f1fbb17": "راه‌اندازی",
  "wp.message.b5037bab5a4a": "راه‌اندازی کلید عبور",
  "wp.message.b7522cb65e91": "پیش از تولید کدهای بازیابی، برنامهٔ احراز هویت، کدهای ایمیلی یا کلید عبور را راه‌اندازی کنید.",
  "wp.message.86d31445fccd": "راه‌اندازی کدهای ایمیلی",
  "wp.message.caa58d4bc38f": "برای تکمیل ورود، احراز هویت دومرحله‌ای را راه‌اندازی کنید.",
  "wp.message.c5338ccf8fa1": "برنامهٔ احراز هویت را راه‌اندازی کنید",
  "wp.message.dbdf27e5db8d": "در حال راه‌اندازی",
  "wp.message.1dbcee682443": "ورود با Google",
  "wp.message.ab04d2e4de13": "Site Kit > تنظیمات > اتصال سرویس‌های بیشتر",
  "wp.message.3bcb66ee1a6f": "کد شش‌رقمی",
  "wp.message.5f365c1b7347": "اعلان وضعیت",
  "wp.message.41af78359ce6": "تایپوگرافی متن",
  "wp.message.b68943b35209": "این تأیید پذیرفته نشد. دوباره تلاش کنید.",
  "wp.message.1f0ec82c0aa3": "این حساب دیگر وجود ندارد.",
  "wp.message.69f681b49ab5": "کد برنامهٔ احراز هویت معتبر نیست.",
  "wp.message.d36fa8e752cb": "کد ایمیلی معتبر نیست.",
  "wp.message.dc568f104dd0": "درخواست راه‌اندازی کلید عبور منقضی شد. دوباره شروع کنید.",
  "wp.message.582bb8974236": "تغییر تنظیمات امنیتی ممکن نشد. پس از پایان سایر درخواست‌های راه‌اندازی، صفحه را تازه‌سازی و دوباره تلاش کنید.",
  "wp.message.aadd9cf83b66": "سرور نمی‌تواند رمز محرمانهٔ احراز هویت را به‌صورت امن رمزگذاری کند. با مدیر سایت تماس بگیرید.",
  "wp.message.e244f187f696": "شما",
  "wp.message.06b2bc8020aa": "این کار همهٔ روش‌های احراز هویت دومرحله‌ای، کلیدهای عبور و کدهای بازیابی این حساب را حذف می‌کند. ادامه می‌دهید؟",
  "wp.message.51b6cdcc3257": "تلاش‌های تأیید بیش از حد است. برای شروع دوباره رمز عبورتان را وارد کنید.",
  "wp.message.aba49fa16207": "تلاش‌های تأیید بیش از حد است. ورود با Google را دوباره شروع کنید.",
  "wp.message.d2d68041b53d": "تبدیل",
  "wp.message.f586fd3f8ba1": "احراز هویت دومرحله‌ای از حسابتان حذف شد. اگر این تغییر را انجام نداده‌اید، رمز عبورتان را بازنشانی کنید و فوراً با مدیر سایت تماس بگیرید.",
  "wp.message.87f08d30fbad": "استفاده از کلید عبور",
  "wp.message.a212e247b569": "از Windows Hello، Touch ID، Face ID، احراز هویت زیستی یا کلید امنیتی FIDO2 استفاده کنید.",
  "wp.message.b0f196cf2a59": "برای تکمیل ورود از برنامهٔ احراز هویت، کد ایمیلی، کلید عبور یا کد بازیابی استفاده کنید.",
  "wp.message.8e9144afb01c": "روش تأیید",
  "wp.message.cc4d85614069": "کد تأیید یا بازیابی",
  "wp.message.eea2745e2867": "تأیید",
  "wp.message.7a970cb4533f": "تأیید و ورود",
  "wp.message.4d8f4755ac09": "هویتتان را تأیید کنید",
  "wp.message.2fcac134b4c3": "برنامهٔ احراز هویت را تأیید کنید",
  "wp.message.428defb7b530": "کد ایمیلی را تأیید کنید",
  "wp.message.e981ddae45d8": "هشدار",
  "wp.message.41298e82bbe5": "کد تأییدی با اعتبار کوتاه به i•••@example.com می‌فرستیم.",
  "wp.message.7da797ee45af": "WordPress نتوانست ایمیل تأیید را ارسال کند.",
  "wp.message.276ff9d215e1": "WordPress نتوانست ایمیل راستی‌آزمایی را ارسال کند.",
  "wp.message.e0259a80364a": "در حال کار در Bricks",
  "wp.message.3310c5a30ba0": "باید وارد حساب شوید.",
  "wp.message.8fc36a487791": "در اولین ورود از شما خواسته می‌شود احراز هویت دومرحله‌ای را راه‌اندازی کنید.",
